import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"師","description":"焦氏易林注 - 師","frontmatter":{"title":"師","description":"焦氏易林注 - 師"},"headers":[],"relativePath":"zh/classics/jiaoyilin/007.md","filePath":"zh/classics/jiaoyilin/007.md"}'),l={name:"zh/classics/jiaoyilin/007.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="師" tabindex="-1">師 <a class="header-anchor" href="#師" aria-label="Permalink to “師”">​</a></h1><h3 id="師-1" tabindex="-1">師 <a class="header-anchor" href="#師-1" aria-label="Permalink to “師”">​</a></h3><h3 id="師之乾" tabindex="-1">師之乾 <a class="header-anchor" href="#師之乾" aria-label="Permalink to “師之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>一簧兩舌，侫言諂語。三姦成虎，曾母投杼。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此全用《師》象。震為音，故曰簧，坎數一，故曰一簧。震為舌，坤數二，故曰兩舌。震數三，坤為姦，乾為虎，故曰三姦成虎。坤為母、為重，曾與層同，故曰曾母。坎為杼，事詳坤之夬註。侫言諂語，言坎上下皆兌口，凡《易》雲有言者象皆如此。○虎，從汲古，宋元皆作古。</p><h3 id="師之坤" tabindex="-1">師之坤 <a class="header-anchor" href="#師之坤" aria-label="Permalink to “師之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>春桃生花，季女宜家。受福且多，在師中吉，男為邦君。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>此用《遇》卦師象。震為春、為桃、為花、為生。坎為室家，伏巽為季女。《詩召南》：「桃之夭夭，灼灼其華；之子於歸，宜其室家」。坤為邦，震為長男、為君，故曰男為邦君。○邦，宋元本作封，依汲古。陳樸園引「無在師中，吉」四字，並謂似是武王娶邑薑事，故曰邦君。與毛異。</p><h3 id="師之屯" tabindex="-1">師之屯 <a class="header-anchor" href="#師之屯" aria-label="Permalink to “師之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>殊類異路，心不相慕。牝牛牡豭，獨無室家。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>艮震皆為道路，相反故曰殊類異路、心不相慕。坎為心也。坎為牝豭，坤為牝牛，艮為室家，坤寡坎孤，故無室家。</p><h3 id="師之蒙" tabindex="-1">師之蒙 <a class="header-anchor" href="#師之蒙" aria-label="Permalink to “師之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>折若蔽日，不見稚叔。三足孤烏，遠其元夫。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>《楚辭》：「折若木以蔽日」，若，木名也。坎為木、為折，離伏，故曰蔽日。艮為叔、為少，坎隱，故不見稚叔。震為足，數三，艮為鳥、為烏，故曰三足孤烏。震為夫、為長，故曰元夫。○若、日，從宋元本，汲古作葉、作目，非。遠，汲古作達，亦非。</p><h3 id="師之需" tabindex="-1">師之需 <a class="header-anchor" href="#師之需" aria-label="Permalink to “師之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>雀東求粒，誤入罔域。賴仁君子，脫服歸息。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>通《晉》。離為雀，位東，艮為求，艮為反，震為粒，故曰雀東求粒。離為網罭，乾為仁、為君子，震為服、為歸，震反為艮，艮止，故曰脫服、曰歸息。《詩》「兩服上襄」註：兩服者，馬之上駕也。脫服，即馳駕也。○丁晏雲：罔域即網罭。服，宋本、汲古訛復，元本訛腹，皆不知服訓而妄改。○離東之證。</p><h3 id="師之訟" tabindex="-1">師之訟 <a class="header-anchor" href="#師之訟" aria-label="Permalink to “師之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>王孫季子，相與孝友。明允篤誠，升擢薦舉，為國乾輔。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>通《明夷》。震為王、為子，反艮為孫、為季，坤順，故孝友。離明坎信，故曰明允篤誠。震為升擢薦舉。坤為國，震為輔。○乾，依宋元本，汲古作藩。薦，宋本元作家，依汲古。</p><h3 id="師之師" tabindex="-1">師之師 <a class="header-anchor" href="#師之師" aria-label="Permalink to “師之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>鳥鳴呼子，哺以酒脯。高樓之處，子來歸母。嗇人成功，年歲大有，妬婦無子。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>震為鳥、為鳴、為子、為哺。坎為酒、為脯、為室，坤為重，故曰高樓。坤母震子，震歸，故曰子來歸母。震為人，坤為吝嗇，故曰嗇人。嗇人，鄉官也。震為功，坤為年歲、為積聚，故大有。坎為妬，伏巽為婦，坤喪故無子。○鳥，宋元本作烏。嗇，宋元本作穡。</p><h3 id="師之比" tabindex="-1">師之比 <a class="header-anchor" href="#師之比" aria-label="Permalink to “師之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>刖樹無枝，與子分離。饑寒莫食，獨泣哀悲。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>艮為刀、為手、為木，故曰刖樹。坎為孤，故曰無枝。坎為寒，坤為飢，兌口為食，兌伏，故莫食。坎為獨、為泣、為悲哀。第二句象未詳。○刖樹，從宋本，汲古作削木。泣，汲古作立，依宋元本。</p><h3 id="師之小畜" tabindex="-1">師之小畜 <a class="header-anchor" href="#師之小畜" aria-label="Permalink to “師之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>舜升大禹，石夷之野。徵詣玉闕，拜治水土。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通《豫》。震為帝、為升，故曰舜升大禹。艮為石，坤為夷、為野，故曰石夷之野。《洛書靈淮聽》：「禹出石夷」是也。震為徵、為詣、為玉，艮為闕、為拜，坎為水、為土。○玉，依宋元本，汲古作王，亦合。○坎為土證。又按：《史記夏本紀》註：「楊雄《蜀王本紀》雲：『禹生於石紐』，《括地誌》：『茂州汶川縣石紐山』，《華陽國志》雲：『今夷人共營其地不敢居。』」石夷或指此事。詳坤之中孚。</p><h3 id="師之履" tabindex="-1">師之履 <a class="header-anchor" href="#師之履" aria-label="Permalink to “師之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>義不勝情，以欲自營。見利危躬，滅君令名。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。坤為義，坎為情、為欲，巽為利，艮為射，坎危兌見，故曰見利危躬。震為君，艮為名，坎滅，故曰滅君令名。○躬，宋元本皆作寵，依汲古。</p><h3 id="師之泰" tabindex="-1">師之泰 <a class="header-anchor" href="#師之泰" aria-label="Permalink to “師之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>三人北行，六位光明。道逢淑女，與我驥子。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>震為人，數三，故曰三人北行。坤為北，乾數六，伏艮為位、為光明，故曰六位光明。艮為道，伏巽為淑女、為震婦，故曰與我驥子。震為馬、為子。○《坤》北之證。</p><h3 id="師之否" tabindex="-1">師之否 <a class="header-anchor" href="#師之否" aria-label="Permalink to “師之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>羿張烏號，彀射天狼。柱國雄勇，鬬死滎陽。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>坤為惡，故曰羿。羿簒夏，《論語》：「羿善射」。鳥號，弓名。伏震為號、為射，艮為烏，故曰烏號、曰彀射。艮為狼，上乾，故曰天狼，星名也。坤為國，艮為柱，故曰柱國。乾健，故曰雄勇。坤為死、為水，故戰死滎陽。滎，水名。按：《史記陳涉世家》：「陳王以房君蔡賜為上柱國，後敗死。」不著死地，死滎陽者為李歸，又吳叔雖死滎陽，為部下所殺，非鬬死也。林詞或別有所據，抑蔡賜亦死滎陽歟？又噬嗑之旅、井之大過柱皆作趙，或國為人名。</p><h3 id="師之同人" tabindex="-1">師之同人 <a class="header-anchor" href="#師之同人" aria-label="Permalink to “師之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>季姬踟躕，結衿待時。終日至暮，百兩不來。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>離為日，伏坎為暮，乾為百，坤為大，輿數二，故曰百兩，巽伏故不來。季姬，指互巽，大過以巽為女妻。《易林》本之，見巽即謂為少齊，季亦少也。陳樸園雲：案：《左傳》：「齊桓公有長衛姬，少衛姬」，疑《易林》所雲季姬即少衛姬。又同人之隨有「望我城隅，終日至暮，不見齊侯」之語，陳氏並謂其說《衛風靜女》之詩。</p><h3 id="師之大有" tabindex="-1">師之大有 <a class="header-anchor" href="#師之大有" aria-label="Permalink to “師之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>鴻雁翩翩，始怨勞苦。災疫病民，鰥寡愁憂。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。艮為鴻雁、為飛，故曰翩翩。坎為怨、為勞苦、為災病，坤為民、為寡，艮為鰥，坎為寡。○怨，從宋本，汲古作若。鴻雁，《小雅》篇名，林詞全本之《詩》。</p><h3 id="師之謙" tabindex="-1">師之謙 <a class="header-anchor" href="#師之謙" aria-label="Permalink to “師之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>穿胸狗邦，僵離旁春。天地易紀，日月更始。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>坤為腹、為胸，卦一陽在五陰之中，坎為穿，故曰穿胸。坤為邦，艮為狗，故曰狗邦。坤死，故曰僵離，艮手，故曰旁春。坤地。艮為天，艮居醜寅，成始成終，故曰易紀、曰日月更始。坎月，艮為日，震為春，故更始。《爾雅釋地》疏：蠁類有八，五曰穿胸，七曰狗軹，八曰旁春。又《逸周書王會》：「正西昆侖、狗國、貫胸、離、丘。」丁晏雲：狗邦即犬戎，非。又《山海經》有貫胸國，《淮南子墬形訓》有穿胸民。《後漢書南蠻傳》有封離，楊竦破封離是也。又有那離，見《西羌傳》，疑僵離或封離之音訛字。○旁春，元本作旁美，依宋本、汲古。</p><h3 id="師之豫" tabindex="-1">師之豫 <a class="header-anchor" href="#師之豫" aria-label="Permalink to “師之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>北山有棗，使叔壽考。東嶺多慄，宜行賈市。陸梁雌雉，所至利喜。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>艮為山，坤為北，艮為果，故曰北山有棗。艮為叔、為壽考，震為東，艮為嶺、為慄，伏巽為賈市。艮為梁，伏離為雉，震為喜。○雉，依宋元本，常本或訛雄。慄，元本訛粟。</p><h3 id="師之隨" tabindex="-1">師之隨 <a class="header-anchor" href="#師之隨" aria-label="Permalink to “師之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>乾旄旌旗，執幟在郊。雖有寶珠，無路致之。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>震為木、為乾、為羽，故為旄、為旌旗。《左傳》「火焚其旗」即以震為旗。艮手為執，震為寶玉、為路，艮止故無路。《詩墉風》：「了了乾旄，在浚之郊」，毛謂美大夫下賢，茲曰：「雖有寶珠無路致之」，是齊說與毛異。○執，依汲古，宋元作撫。珠，依汲古，宋元本作玉。</p><h3 id="師之蠱" tabindex="-1">師之蠱 <a class="header-anchor" href="#師之蠱" aria-label="Permalink to “師之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>精潔塞淵，為讒所言。證訊詰問，繫於枳溫。甘棠聽斷，怡然蒙恩。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>震為精潔，兌為淵，坎為塞，《詩衛風》：「秉心塞淵」箋：塞，充實。淵，深也。三上正反震，故曰讒言、曰譏問。艮為拘系。枳，地名，在魏郡。溫在河內。巽木為枳，艮火為溫，故曰枳溫。凡《易林》用字，無論地名、人名，無不從象生。巽為棠，初四正反兌，故曰聽斷。兌為耳、為聽、為恩。按：以正反震兌為讒、為詰問，則《易》與《左傳》用覆之處皆得解。繫於枳溫，《左傳僖二十八年》：「會於溫，衛侯與元喧訟，於是衛侯不勝置諸深室」，甘棠聽斷者，《詩召南》甘棠篇，魯韓詩說皆謂召伯聽訟棠下，茲曰蒙恩，似謂召伯能平反冤獄也。○問，宋本、汲古作請，依元本。</p><h3 id="師之臨" tabindex="-1">師之臨 <a class="header-anchor" href="#師之臨" aria-label="Permalink to “師之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>玄黃瘣隤，行者勞罷。役夫憔悴，逾時不歸。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>震為馬、為玄黃，坤弱，故曰玄黃。瘣、隤，皆病也，見《毛詩周南》註。震為行，坤役萬物，故勞疲。坤為役，震為夫、為逾、為時、為歸，坤喪故不歸。○瘣，宋本、汲古作虺，與《毛詩》合，元本作瘣，音義與虺同，特字異耳，說詳賁之小過。</p><h3 id="師之觀" tabindex="-1">師之觀 <a class="header-anchor" href="#師之觀" aria-label="Permalink to “師之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>膚敏之德，發憤晨食。虜豹禽說，以成主德。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>艮為膚，巽為敏，伏震為發、為憤、為晨、為食。艮為拘系、為虜、為禽，艮為豹。伏兌為說，故曰虜豹禽說。豹，魏王豹。說，代相夏說也。見《史記淮陰侯傳》。伏震為主。○說，從宋元本，汲古訛越。多「為王求福」四字。晨食，亦用《淮陰侯傳》，汲古、宋本作忘食，後人臆改，依元本。</p><h3 id="師之噬嗑" tabindex="-1">師之噬嗑 <a class="header-anchor" href="#師之噬嗑" aria-label="Permalink to “師之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>採唐沬鄉，要我桑中。失信不會，憂思約帶。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>艮為採，震為唐。唐，菜也。艮為鄉，坎隱，故曰沬鄉。沬，衛邑，見《衛風》。震為要、為桑，坎為中，故曰桑中，《詩》「期我乎桑中」。坎為信、為失，艮止，故不會。坎為憂思，伏巽為帶、為約。約帶即結帶。按：《檜風素冠篇》：「我心蘊結」，《曹風鳲鳩篇》：「心如結兮」，正義雲：「憂愁不散，如物之裹結」，即約帶之義也。楊慎謂即古詩「衣帶日以緩」之義，非。</p><h3 id="師之賁" tabindex="-1">師之賁 <a class="header-anchor" href="#師之賁" aria-label="Permalink to “師之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>伯寧子福，惠我邦國。蠲除苛殘，使季無患。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>震為伯、為子、為福。艮為邦國、為季，坎為患，震樂，故無患。</p><h3 id="師之剝" tabindex="-1">師之剝 <a class="header-anchor" href="#師之剝" aria-label="Permalink to “師之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>讒父佞雄，賊亂邦國。生雖忠孝，敗困不福。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>通《夬》。兌為言，乾為言，兌口與乾言相背，故曰讒父佞雄。父，長者之稱，言為讒人之長，佞者之雄也。坤為賊、為亂、為邦國。○父，依汲古，宋本、元本作言。讒父佞雄，對文。父亦乾象。困，宋元本作恩，依汲古。淮，汲古作離，依宋元本。又：不福，宋元本作不足，依汲古。○此可釋《夬》「聞言不信」義。</p><h3 id="師之復" tabindex="-1">師之復 <a class="header-anchor" href="#師之復" aria-label="Permalink to “師之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>淵泉堤防，水道利通。順註湖海，邦國富有。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>坤為淵、為泉，坤閉為堤防。震為道，坤水，故曰水道。震為通，伏巽為利，坤為順、為湖海、為邦國、為富有。○利通，依元本，與防韻，宋本、汲古作通利，非。</p><h3 id="師之無妄" tabindex="-1">師之無妄 <a class="header-anchor" href="#師之無妄" aria-label="Permalink to “師之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>江南多蝮，螫我手足。冤繁詰屈，痛徹心腹。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>乾為江河，位南，故曰江南。蝮，毒蛇也。伏坤為螫。艮手震足，正反震，故曰冤繁，正反艮，故曰詰屈。伏坤為心、為腹。</p><h3 id="師之大畜" tabindex="-1">師之大畜 <a class="header-anchor" href="#師之大畜" aria-label="Permalink to “師之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>三人俱行，別離獨宿。一身五心，反覆迷惑，亂無所得。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>震為人、為行，數三，故曰三人俱行。一陽止上，故曰別離獨宿。通《萃》。坤為身，乾卦數一，故曰一身。巽卦數五，伏坤為心，故曰五心。三至上正覆巽，坤迷，故反覆迷惑。坤虛，故亂無所得。○宿，從汲古，宋元本作食。</p><h3 id="師之頤" tabindex="-1">師之頤 <a class="header-anchor" href="#師之頤" aria-label="Permalink to “師之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>鴉鳴庭中，以戎災凶。重門擊柝，備不速客。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>艮為鴉、為庭，震為鳴。坤為災凶，古人常以鴉鵲鳴為占。艮為門，正反艮，故曰重門。震為柝、為鳴，艮為擊，震為客。○鴉，從宋元本，汲古作鶩，非。○此可釋《繫辭》頤與豫象同。</p><h3 id="師之大過" tabindex="-1">師之大過 <a class="header-anchor" href="#師之大過" aria-label="Permalink to “師之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>功成事就，拱手安居。立德有言，坐飭貢賦。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>通《頤》。震為功，艮為成，坤為事，艮為拱、為手、為安居。震為立、為德、為言，艮為坐。坤為貢賦。震為飭。全用旁通。○飭，依汲古，宋元作飾。飾飭古通。</p><h3 id="師之坎" tabindex="-1">師之坎 <a class="header-anchor" href="#師之坎" aria-label="Permalink to “師之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>國亂不安，兵革為患。掠我妻子，家中饑寒。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>中爻艮為國，震動，故不安。艮為兵、為革，坎為患。艮手為掠，震子，伏巽為妻，艮為家，坎為寒，伏離為飢。○艮為兵證。</p><h3 id="師之離" tabindex="-1">師之離 <a class="header-anchor" href="#師之離" aria-label="Permalink to “師之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>戴堯扶禹，松喬彭祖。西過王母，道路夷易，無敢難者。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>通《坎》。中爻震為帝，故曰堯禹。艮為扶、為戴，艮堅為松喬、為彭祖。解詳訟之家人。坎為西，震為王，巽為母，故曰王母。艮為道路，坎平，故道路夷易。○松，汲古作從，過作遇，依宋元本。艮為祖，可釋《易》。松喬、彭祖，皆古仙人名。</p><h3 id="師之咸" tabindex="-1">師之咸 <a class="header-anchor" href="#師之咸" aria-label="Permalink to “師之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>長尾蜲蛇，畫地成河。深不可涉，絕無以北，惆悵嘳息。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>艮為尾，巽長，故曰長尾。巽為蛇，故曰蜲蛇。蜲蛇，蟲名也。《管子水地篇》「蜲一頭兩身，其形若蛇，其長八尺」是也。通《損》。坤為地、為江河。艮為畫。坤水臨大澤，故曰深不可涉。兌為絕，坤位北，兌口為嘳息。嘳息，猶嘆息。○蜲，依噬嗑之覆校改。北，宋元皆作比，依汲古。惆悵，汲古作惆然，依宋元本。嘳字依汲古，宋元本皆訛會。《說文》：「嘳，大息也」。《晏子春秋》「嘳然而嘆息」。汲古作思，依宋元本。</p><h3 id="師之恒" tabindex="-1">師之恒 <a class="header-anchor" href="#師之恒" aria-label="Permalink to “師之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>乘龍從霓，徵詣北闕。乃見宣室，拜守東域。鎮慰黎元，舉家蒙福。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>震為龍、為乘，巽為霓。霓，日旁氣。伏艮為闕。坤為北，震往為詣、為宣明，艮室，故曰宣室。艮為拜、為守，震東，故守東域。坤為黑、為黎元。艮家震福。○坤北證。○域，依汲古，宋元本皆作城。</p><h3 id="師之遯" tabindex="-1">師之遯 <a class="header-anchor" href="#師之遯" aria-label="Permalink to “師之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>土與山連，終身無患。天地高明，萬歲長安。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>艮為土，乾為山，故曰土與山連。艮為終、為身，伏震為樂，故終身無患。乾天坤地，巽高艮明，故曰高明。乾為萬歲。艮安巽長，故曰長安。○艮光明證。</p><h3 id="師之大壯" tabindex="-1">師之大壯 <a class="header-anchor" href="#師之大壯" aria-label="Permalink to “師之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>久旱水涸，枯槁無澤。虛修其德，末有所獲。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>通《觀》。艮為火，故旱、故水涸。坤為水，巽為枯槁，枯槁故無澤。坤為虛，虛故無獲。○艮火可解無妄旱卦。</p><h3 id="師之晉" tabindex="-1">師之晉 <a class="header-anchor" href="#師之晉" aria-label="Permalink to “師之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>依山倚地，凶危不至。上清下凈，君受其利。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>坤地艮山。艮為依倚，故曰依山倚地。坤為凶，坎為危，艮安，故凶危不至。艮上坤下，坎水，故曰清凈。伏乾為君。○山，宋元本作天，依汲古。宋元多「受福大明」四字，依汲古。凈，汲古作降，依宋元本。</p><h3 id="師之明夷" tabindex="-1">師之明夷 <a class="header-anchor" href="#師之明夷" aria-label="Permalink to “師之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>火烈不去，必殪僵僕。燔我衣裾，禍不可悔。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>離火。震往為去，坎陷，故不去，不去必僵僕。坤為死也。震為衣裾，離為燔，坤為我、為禍。○禍，依元本，宋本作福。</p><h3 id="師之家人" tabindex="-1">師之家人 <a class="header-anchor" href="#師之家人" aria-label="Permalink to “師之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>配合相迎，利之四鄉。欣喜興懌，所言得當。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>此用《師》象。坎為配合，巽為利，震為之，震卦數四，故曰利之四鄉。坤為鄉，震為樂、為興、為言。○懌，從汲古，宋元訛釋。</p><h3 id="師之睽" tabindex="-1">師之睽 <a class="header-anchor" href="#師之睽" aria-label="Permalink to “師之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>清人高子，久屯外野。逍遙不歸，思我慈母。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>高子，高克。清，鄭邑名。《詩》序：「鄭文公惡高克，使將兵河上，久不召，兵散，故賦《清人》詩」，此似用遇卦師象。○逍，宋元本、汲古皆作道，依局本。</p><h3 id="師之蹇" tabindex="-1">師之蹇 <a class="header-anchor" href="#師之蹇" aria-label="Permalink to “師之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>武庫軍府，甲兵所聚。非里邑居，不可舍止。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>此兼用《師》象。震為武，坤為軍、為府庫。艮為甲兵，坎為聚，艮為邑、為里居、為舍止，多兵故不可舍止。○艮亦為甲兵之證。</p><h3 id="師之解" tabindex="-1">師之解 <a class="header-anchor" href="#師之解" aria-label="Permalink to “師之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>三德五才，和合四時。陰陽順序，國無咎災。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>《書洪範》：「六三德一曰正直，二曰剛克，三曰柔克」。五材，金木水火土也。震數三，故曰三德。坎數五，震木，故曰五材。坎為和、為合，震為時，卦數四，故曰四時。離坎雜居，故曰陰陽順序。○才，依宋本，汲古作材。</p><h3 id="師之損" tabindex="-1">師之損 <a class="header-anchor" href="#師之損" aria-label="Permalink to “師之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>解衣毛羽，飛入大都。晨門戒守，鄭忽失家。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>震為解、為衣、為毛羽、為飛。坤為大都。艮為門，震為晨，故曰晨門。艮為守，震言為戒，故曰戒守。坤為鄭，《釋名》「鄭，町也，地多平町。町，然也。町田，區畔也」，故坤為鄭。純取卦形，坤亡，故曰鄭忽失家。艮為家也。鄭忽，鄭昭公名，《左傳桓十一年》「鄭忽出奔衛」是也。○坤為鄭象證。</p><h3 id="師之益" tabindex="-1">師之益 <a class="header-anchor" href="#師之益" aria-label="Permalink to “師之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>刖根燒株，不生肌膚。病在心腹，日以焦枯。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>艮為刀兵、為手，故曰刖根。巽下斷，刖根之象。艮為火，故燒株。震巽皆為木株，艮為膚，巽落，故不生。坤為腹、為心、為病，艮火為焦枯。伏乾為日，是可為艮刀、艮火證。○刖，依元本，宋本、汲古作削，皆淺人妄改。</p><h3 id="師之夬" tabindex="-1">師之夬 <a class="header-anchor" href="#師之夬" aria-label="Permalink to “師之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>文山紫芝，雍梁朱草。生長和氣，王以為寶。公屍侑食，福祿來處。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>通《剝》。艮山坤文，故曰文山。艮形似芝，乾舍離。離宮色紫，故曰紫芝。乾為大赤，故曰朱草。兌西，故曰雍梁。乾為生長，兌悅，故曰和。乾為王、為寶、為父、為公。坤為屍，兌為食，乾為福祿。《詩小雅》：「公屍來燕來處，福祿來下」。陳樸園雲《鳧鷖》詩。《鄭箋》以為第三章為祭天地山川之詩，蓋王者德配天地，紫芝、朱草，符瑞並臻也。○四五句依同人之剝增，宋元、汲古諸本皆遺失，不惟不協，事義皆缺。</p><h3 id="師之姤" tabindex="-1">師之姤 <a class="header-anchor" href="#師之姤" aria-label="Permalink to “師之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>多載重負，捐棄於野。予母誰子，但自勞苦。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>通《復》。坤為多載重負、為捐棄、為野。坤為母，震為子，震伏坤死，故曰誰子，言無子也。坤役萬物故勞苦，坤為自。○第三句從宋元本，汲古及常本皆作小任其大，非。</p><h3 id="師之萃" tabindex="-1">師之萃 <a class="header-anchor" href="#師之萃" aria-label="Permalink to “師之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>鳧雁啞啞，以水為家。雌雄相和，心志娛樂，得其歡欲。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>艮為鳧雁，正反兌口，故曰啞啞。艮為家，坤為水，兌雌艮雄，坎為和，故曰相和。坎為心志，兌悅為娛樂、為歡。○艮為鳥證。漸、小過得解，詳《焦氏易詁》。</p><h3 id="師之升" tabindex="-1">師之升 <a class="header-anchor" href="#師之升" aria-label="Permalink to “師之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>耳目盲聾，所言不通。佇立以泣，事無成功。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>兌為耳，坤閉故聾。離為目，兌半離、目不全，故盲。兌口為言，坤閉，故不通。震為立，坎為泣，坤為事，坤喪，故無功。</p><h3 id="師之困" tabindex="-1">師之困 <a class="header-anchor" href="#師之困" aria-label="Permalink to “師之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>天官列宿，五神所舍。宮闕堅固，君安其居。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>通《賁》。艮為官，在上，故曰天官。艮為星，故曰列宿。坎亦為宿也。震為神，坎數五，故曰五神。五神，金木水火土五星也。艮為舍、為宮闕、為堅固、為安居。震為君。○震為神證。</p><h3 id="師之井" tabindex="-1">師之井 <a class="header-anchor" href="#師之井" aria-label="Permalink to “師之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>範子妙材，戮辱傷膚。後相秦國，封為應侯。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>巽為蟲，故曰範。《禮檀弓》：「範則冠而蟬有緌」，註：範，蠭也。伏震為子，故曰範子。巽為材，兌為毀折，離為膚，故戮辱傷膚。伏震為相，艮為國，兌西，故曰相秦國。艮為封，伏震為諸侯、為聲，正反震相和答，故曰應侯。《史記範睢傳》：「魏齊笞睢，折脅棄廁中，更溺之後，為秦相，封應侯」，以應侯象正反震，神妙。○第三句依大畜之剝校，各本皆作然後相國。</p><h3 id="師之革" tabindex="-1">師之革 <a class="header-anchor" href="#師之革" aria-label="Permalink to “師之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>秋冬探巢，不得鵲雛。銜指北去，慚我少夫。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>兌為秋，互乾為冬，艮為巢、為手，故曰探巢。兌為鵲雛，坤為失，故不得。兌口為銜，艮為指。坎為北，震往，故曰北去。艮為少夫，坎為慚，故曰慚我少夫。正伏象雜用。</p><h3 id="師之鼎" tabindex="-1">師之鼎 <a class="header-anchor" href="#師之鼎" aria-label="Permalink to “師之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>子畏於匡，厄困陳蔡。德行不危，竟脫厄害。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。震子坎畏。匡，目匡，離象。坎陷，故厄困。震為陳，艮為龜、為蔡，事皆見《論語》。震為行，艮安，故不危，故脫厄害。坤為害。</p><h3 id="師之震" tabindex="-1">師之震 <a class="header-anchor" href="#師之震" aria-label="Permalink to “師之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>鴻飛在陸，公出不復。仲氏任只，伯氏客宿。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>互艮為鴻、為飛、為陸，故曰在陸。震為復、為公、為出，坎陷故不復。坎為仲、為宿，震為伯、為客，首二語見《豳風》，美周公也。震為周，故因以起興。三句見《邶風》。任者，《鄭箋》：相親信也。○以艮為鴻，漸鴻得解。</p><h3 id="師之艮" tabindex="-1">師之艮 <a class="header-anchor" href="#師之艮" aria-label="Permalink to “師之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>鶴鳴九皋，避世隱居。抱朴守貞，竟不隨時。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>互震為鶴、為鳴，艮為皋，震數九，故曰九皋。坎為隱避，艮為居、為抱、為守。震木為樸，艮為貞、為時，坎隱，故不隨時。○貞，從汲古，宋元本作真。義同，而貞切艮象。隨時，依宋元本，汲古作相隨。鶴鳴，《小雅》篇名，序謂誨宣王求賢而隱者。茲雲隱居，義與毛同。</p><h3 id="師之漸" tabindex="-1">師之漸 <a class="header-anchor" href="#師之漸" aria-label="Permalink to “師之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>舜升大禹，石夷之野。徵詣王庭，拜治水土。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>解見乾之中孚、師之小畜，漸伏象與前同。</p><h3 id="師之歸妹" tabindex="-1">師之歸妹 <a class="header-anchor" href="#師之歸妹" aria-label="Permalink to “師之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>左輔右弼，金玉滿堂。常盈不亡，富如厫倉。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>本象、對象雜用。解見蒙之坤。○艮金之證○堂，依元本，宋本、汲古作匱。</p><h3 id="師之豐" tabindex="-1">師之豐 <a class="header-anchor" href="#師之豐" aria-label="Permalink to “師之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>崔嵬北岳，天神貴客。衣冠不已，蒙被恩德。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>通《渙》。巽高，故崔嵬。艮山坎北，故曰北。岳震為神、為客，艮陽在上而貴，故曰天神貴客。艮為冠，震為衣、為恩德。○艮貴證。</p><h3 id="師之旅" tabindex="-1">師之旅 <a class="header-anchor" href="#師之旅" aria-label="Permalink to “師之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>空槽註器，獖彘不至。張弓祝雞，雄父飛去。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>艮為槽，互巽為獖彘。《莊子達生篇》「以瓦註者巧」，《釋文》「註，擊也」。註器者，擊器使獖彘聞，然槽空無食，亦不至也，艮止，故曰不至。艮少，故曰獖彘。伏坎為弓，震為張，故曰張弓。巽為雞，兌口為祝。祝者，呼聲。《說苑》「猶舉杖而祝狗，張弓而祝雞」。伏震為雄、為父、為飛，巽伏，故曰飛去。○父，汲古作鳩，從宋元本。獖，依宋元，汲古作（左反犬右屯）。註器，各本作住豬，至作到，依汲古咸之困校。器、至韻。</p><h3 id="師之巽" tabindex="-1">師之巽 <a class="header-anchor" href="#師之巽" aria-label="Permalink to “師之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>蠻夷戎狄，太陰所積。涸冰冱寒，君子不存。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>初四大坎，故曰太陰。蠻夷戎狄，皆陰類。坎為冰、為寒，艮為君子，二至四艮伏，故君子不存。○蠻夷，原作胡蠻，冱作凍，均依既濟之謙校。</p><h3 id="師之兌" tabindex="-1">師之兌 <a class="header-anchor" href="#師之兌" aria-label="Permalink to “師之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>甘露醴泉，太平機關。仁德感應，歲樂民安。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>解見屯之謙。兌通艮，艮象與謙同。</p><h3 id="師之渙" tabindex="-1">師之渙 <a class="header-anchor" href="#師之渙" aria-label="Permalink to “師之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>惡來呼伯，慎驚外客。甲守閉宅，以備凶急。臨折之憂，雖滅無災。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>丁雲：惡來，紂臣名，然此似非用事。惡來，猶聞凶耗也，故呼伯。震為呼、為伯，巽為旅客，在外，故不驚外客。震為驚，艮為甲、為守、為宅，坎閉，故曰閉宅。伏兌為急、為毀折，坎為憂、為滅、為災，震樂故無災。○艮剛在外為甲證。○甲、閉、急，依宋本，汲古作中、作閑、作黠，非。</p><h3 id="師之節" tabindex="-1">師之節 <a class="header-anchor" href="#師之節" aria-label="Permalink to “師之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>日月相望，光明盛昌。三聖茂功，仁德大隆。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>坎為月，艮為日、為觀，正反艮故曰相望。艮為光明，震為盛昌。坎為聖，震數三，故曰三聖。震為茂、為功、為仁德、為隆。三聖，指文、武、周公。</p><h3 id="師之中孚" tabindex="-1">師之中孚 <a class="header-anchor" href="#師之中孚" aria-label="Permalink to “師之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>葛藟蒙棘，華不得實。讒佞亂政，使恩壅塞。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>震為葛藟，伏大坎為棘，故曰蒙棘。兌為華，艮為實，巽隕，故不實。中爻正反震，故曰讒佞。正覆艮，艮止，故壅塞。兌為恩澤。葛藟，《唐風》篇名，毛謂刺晉獻公好攻戰，茲謂刺讒佞，與毛異。</p><h3 id="師之小過" tabindex="-1">師之小過 <a class="header-anchor" href="#師之小過" aria-label="Permalink to “師之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>鄰不我顧，而望玉女。身多癩疾，誰肯媚者。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>震為東，故曰鄰。艮陽在上為望。震為玉，兌為女，故曰玉女。艮為身，多節，故曰癩疾。兌為媚。○媚，從宋元本，汲古作媍。</p><h3 id="師之既濟" tabindex="-1">師之既濟 <a class="header-anchor" href="#師之既濟" aria-label="Permalink to “師之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>精誠所在，神之為輔。德教尚忠，彌世長久。三聖茂功，多受福祉。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此用《師》象。坎為精誠，震為輔、為教。坎為忠，故曰尚忠。坤為世，重坤，故曰彌世長久。坎為聖，震數三，故曰三聖。震為功、為福佑。○神之為輔，依元本，宋本、汲古皆作「神為之輔」。忠，依宋元本，汲古作中。《史記》：「夏之政忠」。祉，依宋本，汲古、元本作佑。茂功，依《節》林，宋元本作尚功，汲古作與為。</p><h3 id="師之未濟" tabindex="-1">師之未濟 <a class="header-anchor" href="#師之未濟" aria-label="Permalink to “師之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>鑽木取火，掘地索水。主母饑渴，子為心禍。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>此仍用《師》象。伏《同人》。巽木，離火，《師》坤地坎水，坤為母，震為主，故曰主母。震為子，坎為心。○水，依元本，宋本、汲古作泉。子，宋元本作手，依汲古。禍，汲古作福，依宋元本。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
